// ===================== 11.5 =====================
out.push(pb());
out.push(h2('11.5  The form with no field for it'));
out.push(S('Stage 1 · Get ready'));
out.push(A('**a** Open. ⚠ **The heading word for word, and then what you actually have.** **In most classes eight of the ten are a field that assumes one of something where the thing being recorded has two.** **Write the ten headings and read them aloud yourself, slowly** — **the assumption is audible and the room will hear it in somebody else\'s heading before it hears it in its own.**'));
out.push(A('**b** Problems of form: **2** and **5**. ⚠ **One box for a reference the system produces in two documents; one line for a date awarded in two stages.** **1 and 3 are content** — **a judgement and an unsupported conclusion — and 4 is a definition problem, which is 11.1 and not this cycle.** **The distinction matters because no amount of good writing touches a problem of form.**'));
